parameters.jsCode:
// Parse the AI JSON response safely
const raw = $input.first().json.choices?.[0]?.message?.content || '';
let analysis;
try {
  analysis = JSON.parse(raw);
} catch (e) {
  const m = raw.match(/\{[\s\S]*\}/);
  try { analysis = JSON.parse(m?.[0] || '{}'); } catch { analysis = {}; }
}

const config = $('Configure Analysis').first().json;
const score = analysis.overall_score || 0;
const passed = analysis.pass !== undefined ? analysis.pass : score >= 70;
const grade = analysis.grade || (score >= 90 ? 'A' : score >= 80 ? 'B' : score >= 70 ? 'C' : score >= 60 ? 'D' : 'F');
const scoreEmoji = score >= 80 ? 'Excellent' : score >= 70 ? 'Good' : score >= 60 ? 'Needs Work' : 'Poor';

return [{ json: {
  ...analysis,
  overall_score: score,
  pass: passed,
  grade,
  score_label: scoreEmoji,
  status_text: passed ? 'APPROVED - Ready for publication' : 'NEEDS IMPROVEMENT - See recommendations below',
  config
}}];

